"""Writes `src/asset_index.rs`: every file under `assets/` embedded with `include_bytes!`, sorted by path string.

Run from anywhere:  python3 crates/kb-skills/scripts/gen_assets_index.py
`cargo test -p kb-skills` checks the index against the folder, so a file added to `assets/` without running this
fails the test instead of being left out.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
files = sorted(p.relative_to(ROOT / "assets").as_posix() for p in (ROOT / "assets").rglob("*") if p.is_file())
lines = [
    "//! The skill folders as embedded data (generated by `scripts/gen_assets_index.py`; do not edit).",
    "",
    "/// Every file under `assets/`, by its path below it, sorted by that text.",
    "pub static FILES: &[(&str, &[u8])] = &[",
]
for rel in files:
    lines.append(f'    ("{rel}", include_bytes!("../assets/{rel}")),')
lines.append("];")
(ROOT / "src" / "asset_index.rs").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(len(files), "files")
